250	reg match_cond_reg = 0;
251	reg no_match_reg = 0;
252	
253	always @(posedge clk) begin
254	    if (rst) begin
255	        match_cond_reg <= 0;
256	        no_match_reg <= 0;
257	    end else begin
258	        if (rx_udp_payload_axis_tvalid) begin
259	            if ((!match_cond_reg && !no_match_reg) ||
260	                (rx_udp_payload_axis_tvalid && rx_udp_payload_axis_tready && rx_udp_payload_axis_tlast)) begin
261	                match_cond_reg <= match_cond;
262	                no_match_reg <= no_match;
263	            end
264	        end else begin
265	            match_cond_reg <= 0;
266	            no_match_reg <= 0;
267	        end
268	    end
269	end
